def solve(thick_A=30.0, K_A=7.0, thick_B=15.0, K_B=78.0,
          thick_C=22.0, K_C=17.0, gradient=0.01):
    # Horizontal flow through layered aquifer: transmissivities add
    # Effective transmissivity T = sum(K_i * b_i)
    T = K_A * thick_A + K_B * thick_B + K_C * thick_C  # ft^2/day

    # Flow per unit width q = T * gradient (Darcy)
    q = T * gradient  # ft^2/day (flow per unit width)

    return {
        "1": {"value": q, "unit": "ft^2/day"}
    }

