def solve(radius=100.0, thickness=8.0, Q=75.4, K=30.0, porosity=0.3):
    # Confined aquifer, radial steady-state flow to fully penetrating well.
    # Q = 2*pi*r*b*K*(dh/dr)  =>  dh/dr = Q / (2*pi*r*b*K)
    # Gradient at the edge of the island (r = radius)
    T = K * thickness  # transmissivity, m^2/day
    gradient = Q / (2.0 * math.pi * radius * thickness * K)
    return {
        "1": {"value": gradient, "unit": "dimensionless (m/m)"}
    }

import math

def solve(R=100.0, b=8.0, Q=75.4, K=30.0, n=0.3):
    # Radial flow to a fully penetrating well in a confined aquifer.
    # Seepage (pore) velocity at radius r: v(r) = Q / (2*pi*r*b*n)
    # Travel time from island edge (R) to well (r=0):
    #   t = integral_0^R (2*pi*r*b*n / Q) dr = pi*b*n*R^2 / Q
    #
    # Units: b [m], R [m], Q [m^3/day], n [-]  -> t in days
    t_days = math.pi * b * n * R**2 / Q

    return {
        "1": {"value": t_days, "unit": "days"}
    }

def solve(q=1.0, K1=20.0, K2=5.0, K3=10.0, b1=10.0, b2=20.0, b3=30.0):
    # Flow perpendicular to layers: harmonic mean weighted by thickness
    total_b = b1 + b2 + b3
    sum_ratio = b1 / K1 + b2 / K2 + b3 / K3
    K_perp = total_b / sum_ratio
    return {"1": {"value": K_perp, "unit": "m/day"}}

