def solve(H=0.5, h1=1.0, V1=30.0, CD=0.6):
    # Physical constants
    rho = 1000.0  # water density, kg/m^3

    # Drag force per unit width on the baffle
    # F_D = CD * (1/2) * rho * V1^2 * H   (per unit width)
    # Approach velocity near V1, baffle height H is the projected area per unit width
    FD = CD * 0.5 * rho * V1**2 * H  # N per m width

    return {
        "1": {"value": FD, "unit": "N/m"}
    }
